# 猜数字游戏
import random

def play():
    target = random.randint(1, 100)
    count = 0
    print("我已经想好了一个 1 到 100 的数字。")
    while True:
        text = input("请输入你的猜测，或输入 q 退出：")
        if text.lower() == "q":
            print("已退出，本次答案是：", target)
            break
        try:
            guess = int(text)
        except ValueError:
            print("请输入整数，例如 35")
            continue
        if guess < 1 or guess > 100:
            print("范围是 1 到 100，请重新输入")
            continue
        count += 1
        if guess < target:
            print("猜小了，再大一点")
        elif guess > target:
            print("猜大了，再小一点")
        else:
            print(f"恭喜猜对！你一共猜了 {count} 次")
            break

if __name__ == "__main__":
    play()

