# 学生成绩管理器
def add_student(students, name, score):
    students.append({"name": name, "score": score})

def average_score(students):
    if not students:
        return 0
    total = sum(item["score"] for item in students)
    return total / len(students)

def top_student(students):
    if not students:
        return None
    return max(students, key=lambda item: item["score"])

def failed_students(students):
    return [item for item in students if item["score"] < 60]

def show_report(students):
    print("学生成绩表：")
    for item in sorted(students, key=lambda x: x["score"], reverse=True):
        print(f"{item['name']}：{item['score']} 分")
    print(f"平均分：{average_score(students):.1f}")
    top = top_student(students)
    if top:
        print(f"最高分：{top['name']} {top['score']} 分")
    failed = failed_students(students)
    print("不及格：", [item["name"] for item in failed])

def main():
    students = []
    add_student(students, "小明", 88)
    add_student(students, "小红", 95)
    add_student(students, "小刚", 58)
    show_report(students)

if __name__ == "__main__":
    main()

