# 待办事项管理器
import json

FILE_NAME = "todos.json"

def load_todos():
    try:
        with open(FILE_NAME, "r", encoding="utf-8") as f:
            return json.load(f)
    except FileNotFoundError:
        return []

def save_todos(todos):
    with open(FILE_NAME, "w", encoding="utf-8") as f:
        json.dump(todos, f, ensure_ascii=False, indent=2)

def add_todo(todos, title):
    todos.append({"title": title, "done": False})

def finish_todo(todos, number):
    index = number - 1
    if 0 <= index < len(todos):
        todos[index]["done"] = True
        return True
    return False

def show_todos(todos):
    if not todos:
        print("暂无待办")
        return
    for i, item in enumerate(todos, start=1):
        mark = "✓" if item["done"] else " "
        print(f"{i}. [{mark}] {item['title']}")

def main():
    todos = load_todos()
    while True:
        print("\n1 添加  2 查看  3 完成  4 保存并退出")
        choice = input("请选择：")
        if choice == "1":
            add_todo(todos, input("待办内容："))
        elif choice == "2":
            show_todos(todos)
        elif choice == "3":
            try:
                ok = finish_todo(todos, int(input("完成编号：")))
                print("已完成" if ok else "编号不存在")
            except ValueError:
                print("请输入数字编号")
        elif choice == "4":
            save_todos(todos)
            print("已保存，再见！")
            break
        else:
            print("无效选择")

if __name__ == "__main__":
    main()

