records = []

def add_record(date, topic, minutes):
    records.append({"date": date, "topic": topic, "minutes": minutes})

def show_records():
    if not records:
        print("暂无学习记录")
        return
    for index, record in enumerate(records, start=1):
        print(index, record["date"], record["topic"], record["minutes"], "分钟")

def get_total_minutes():
    total = 0
    for record in records:
        total += record["minutes"]
    return total

def save_records():
    with open("study_records.txt", "w", encoding="utf-8") as file:
        for record in records:
            file.write(record["date"] + "," + record["topic"] + "," + str(record["minutes"]) + "\n")

def load_records():
    try:
        with open("study_records.txt", "r", encoding="utf-8") as file:
            for line in file:
                parts = line.strip().split(",")
                if len(parts) == 3:
                    records.append({"date": parts[0], "topic": parts[1], "minutes": int(parts[2])})
    except FileNotFoundError:
        print("暂无历史记录")

def main():
    load_records()
    while True:
        print("\n1 添加 2 查看 3 统计 4 保存退出")
